test_suite:
test('type-level: extracts [number, string] params', () => {
  type T = MyParameters<(n: number, s: string) => void>;
  const check: T = [42, 'hello'];
  expect(check).toEqual([42, 'hello']);
});

test('type-level: extracts [] for no-arg function', () => {
  type T = MyParameters<() => void>;
  const check: T = [];
  expect(check).toEqual([]);
});

test('type-level: matches built-in Parameters', () => {
  type Fn = (a: boolean, b: number, c: string) => void;
  type Check = MyParameters<Fn> extends Parameters<Fn> ? true : false;
  const check: Check = true;
  expect(check).toBe(true);
});

// __hidden__
test('type-level: single param extracts correctly', () => {
  type T = MyParameters<(x: number) => number>;
  const check: T = [99];
  expect(check).toEqual([99]);
});
